    private void task(Task work,Done done){
        if(busy){toast("Запрос уже выполняется.");return;}busy=true;if(selectionAction!=null){selectionAction.setEnabled(false);selectionAction.setText(prefs.getBoolean("inventoryAppend",false)?"Распознаём новые продукты…":page.equals("review")?"Составляем блюда…":"Распознаём продукты…");}message("Запрос выполняется. Не отправляйте его повторно.");
        worker.execute(()->{Object value=null;Exception error=null;try{value=work.run();}catch(Exception e){error=e;}final Object result=value;final Exception failure=error;
            ui.post(()->{if(isFinishing()||isDestroyed())return;busy=false;if(selectionAction!=null){selectionAction.setEnabled(true);selectionAction.setText(page.equals("review")?CONFIRM_PRODUCTS:"Подобрать блюда");}if(imageAction!=null){imageAction.setEnabled(true);imageAction.setText(photoButtonLabel());}if(failure!=null){
                if(failure instanceof ApiClient.ApiError){ApiClient.ApiError e=(ApiClient.ApiError)failure;if(e.failedJob)prefs.edit().remove("pendingImage").apply();}
                if(prefs.getBoolean("inventoryAppend",false)&&!prefs.contains(SelectionClient.PENDING)&&!prefs.contains(SelectionClient.READY))prefs.edit().remove("inventoryAppend").apply();if(page.equals("home"))home();
                message(failure.getMessage()==null?"Ошибка. Повтор автоматически не отправлен.":failure.getMessage());
            }else try{done.accept(result);}catch(Exception e){message("Не удалось сохранить результат: "+e.getMessage());}});
        });
    }
    private void home(){screen("home","");
        LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);TextView brand=text("К столу",21);brand.setTypeface(null,Typeface.BOLD);header.addView(brand,new LinearLayout.LayoutParams(0,-2,1));Button gear=buttonView("",()->{if(!busy)settings();});gear.setContentDescription("Настройки");gear.setCompoundDrawablesWithIntrinsicBounds(new UiIcon("settings",OLIVE,dp(22)),null,null,null);header.addView(gear,new LinearLayout.LayoutParams(dp(48),dp(48)));body.addView(header);
        eyebrow("Готовим без лишнего");title("Что приготовим?");muted("Добавьте продукты — подберём блюда.");space();
        if(productPhotos.isEmpty())card(()->{body.setBackground(background(SOFT));body.setMinimumHeight(dp(132));body.setFocusable(true);body.setContentDescription("Добавить фото продуктов: камера или галерея");body.setOnClickListener(v->photoMenu(false));ImageView camera=new ImageView(this);camera.setImageDrawable(new UiIcon("camera",OLIVE,dp(30)));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(dp(40),dp(40));cp.gravity=Gravity.CENTER;body.addView(camera,cp);TextView upload=text("Добавить фото продуктов",16);upload.setTypeface(null,Typeface.BOLD);upload.setGravity(Gravity.CENTER);upload.setMinHeight(dp(44));upload.setOnClickListener(v->photoMenu(false));body.addView(upload);TextView hint=text("Камера или галерея · до 4 снимков",14);hint.setTextColor(MUTED);hint.setGravity(Gravity.CENTER);body.addView(hint);});
        else {section("Ваши продукты · "+productPhotos.size()+" / 4");photoStrip();if(productPhotos.size()<4)button("Добавить ещё фото",()->photoMenu(false));muted("Снимите полки, морозилку или продукты на столе. Все снимки попадут в один подбор.");}
        link(receiptPhoto==null?"Добавить чек · необязательно":"Заменить фото чека","receipt",()->photoMenu(true));
        if(receiptPhoto!=null)link("Убрать чек","back",()->{receiptPhoto=null;persistInputs();home();});
        quickPreferences();
        if(prefs.contains("reviewedInventory"))link("Проверить список продуктов","arrow",this::reviewProducts);
        if(prefs.contains(SelectionClient.PENDING)||prefs.contains(SelectionClient.READY))card(()->{muted("Прежний подбор можно получить без повторной отправки фото. Ответ сохраняется на сервере до 24 часов.");button(prefs.contains(SelectionClient.READY)?"Открыть готовый подбор":"Проверить прежний подбор",this::resumeSelection);link("Убрать незавершённый подбор","back",()->confirm("Убрать код подбора?","Это не отменит запрос у AnyModel. Следующая отправка фотографий будет новым запросом и может оплачиваться отдельно.",()->{prefs.edit().remove(SelectionClient.PENDING).remove(SelectionClient.READY).remove("inventoryAppend").apply();home();}));});
        if(getSharedPreferences("cooking",0).contains("item"))link("Продолжить готовку","arrow",()->{try{openRecipe(new JSONObject(getSharedPreferences("cooking",0).getString("item","{}")),"history");}catch(Exception e){message("Откройте рецепт из сохранённого.");}});
        button("Подобрать блюда",()->{if(busy)return;if(prefs.contains("reviewedInventory")){reviewProducts();return;}if(productPhoto==null){toast("Сначала добавьте фото продуктов.");return;}
            analyze();});
        muted("Нажимая «Подобрать блюда», вы отправляете фото в AnyModel и поставщику модели. Готовый подбор хранится сервером до 24 часов для восстановления.");
        if(choices.length()>0){section("Последний подбор");JSONObject recent=choices.optJSONObject(0);if(recent!=null)recipeCard(recent,"choices");link("Все подобранные блюда","arrow",()->{if(!busy)showChoices();});}
        else if(history.length()>0){section("Недавно сохранено");JSONObject recent=history.optJSONObject(0);if(recent!=null)recipeCard(recent,"history");}
        else card(()->{TextView intro=text("Три шага до готового блюда",17);intro.setTypeface(null,Typeface.BOLD);body.addView(intro);muted("1. Добавьте фото продуктов\n2. Выберите рецепт\n3. Готовьте по шагам");});
        if(productPhoto!=null)link("Убрать выбранные фотографии","back",()->{productPhotos.clear();productPhoto=null;receiptPhoto=null;persistInputs();home();});
        space();muted("Фото отправляется только с вашего согласия. Для подбора нужен интернет. После простоя сервер может запускаться около минуты.");
    }
    private void photoMenu(boolean receipt){photoMenu(receipt,false);}
    private void photoMenu(boolean receipt,boolean append){
        if(busy)return;if(!append&&!receipt&&productPhotos.size()>=4){toast("Можно добавить до четырёх фото. Уберите лишний снимок в ленте.");return;}receiptTarget=receipt;
        new AlertDialog.Builder(this).setTitle(receipt?"Фото чека":"Фото продуктов").setItems(new String[]{"Снять камерой","Выбрать фотографию"},(d,which)->{
            try{if(which==1){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.setType("image/*");intent.addCategory(Intent.CATEGORY_OPENABLE);intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,!receipt);startActivityForResult(intent,append?21:11);}else{
                File folder=new File(getCacheDir(),"camera");folder.mkdirs();File photo=new File(folder,"capture.jpg");cameraUri=FileProvider.getUriForFile(this,getPackageName()+".files",photo);
                Intent intent=new Intent(MediaStore.ACTION_IMAGE_CAPTURE);intent.putExtra(MediaStore.EXTRA_OUTPUT,cameraUri);intent.addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_READ_URI_PERMISSION);intent.setClipData(ClipData.newRawUri("Фото",cameraUri));startActivityForResult(intent,append?22:12);
            }}catch(Exception e){toast("Не удалось открыть камеру или галерею. Попробуйте другой способ.");}
        }).show();
    }
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK)return;
        if(request==21||request==22){receiveExtraPhotos(request,data);return;}if(request!=11&&request!=12)return;ArrayList<Uri> uris=new ArrayList<>();if(request==12&&cameraUri!=null)uris.add(cameraUri);else if(data!=null&&data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());}else if(data!=null&&data.getData()!=null)uris.add(data.getData());if(uris.isEmpty())return;boolean target=receiptTarget;int capacity=target?1:4-productPhotos.size();if(uris.size()>capacity){toast(target?"Для чека выберите один снимок.":"В ленте может быть не больше четырёх снимков. Выберите меньше.");return;}
        task(()->{ArrayList<byte[]> bytes=new ArrayList<>();for(Uri uri:uris)bytes.add(readJpeg(uri));return bytes;},value->{@SuppressWarnings("unchecked") ArrayList<byte[]> bytes=(ArrayList<byte[]>)value;if(target)receiptPhoto=bytes.get(0);else{productPhotos.addAll(bytes);productPhoto=productPhotos.get(0);}prefs.edit().remove("reviewedInventory").apply();persistInputs();if(request==12)new File(getCacheDir(),"camera/capture.jpg").delete();home();});
    }

    private void receiveExtraPhotos(int request,Intent data){
        if(busy)return;ArrayList<Uri> uris=new ArrayList<>();if(request==22&&cameraUri!=null)uris.add(cameraUri);else if(data!=null&&data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());}else if(data!=null&&data.getData()!=null)uris.add(data.getData());if(uris.isEmpty())return;if(uris.size()>4){toast("Для одного дополнения выберите до четырёх фото.");return;}
        task(()->{ArrayList<byte[]> bytes=new ArrayList<>();for(Uri uri:uris)bytes.add(readJpeg(uri));return bytes;},value->{@SuppressWarnings("unchecked") ArrayList<byte[]> photos=(ArrayList<byte[]>)value;if(request==22)new File(getCacheDir(),"camera/capture.jpg").delete();recognizeExtraPhotos(photos);});
    }
    private void recognizeExtraPhotos(ArrayList<byte[]> photos){
        if(busy)return;if(!prefs.contains("reviewedInventory")){message("Сначала откройте подтверждённый список.");return;}
        if(prefs.contains(SelectionClient.PENDING)||prefs.contains(SelectionClient.READY)){message("Сначала получите прежний подбор — повторный запрос не отправлен.");return;}
        if(photos.isEmpty()||photos.size()>4){message("Выберите от одного до четырёх новых снимков.");return;}
        if(!prefs.edit().putBoolean("inventoryAppend",true).commit()){message("Не удалось сохранить состояние. Фото не отправлены.");return;}reviewProducts();
        task(()->SelectionClient.run(this,new JSONObject().put("mode","recognize").put("images",photoUrls(photos)).put("region",prefs.getString("region","Россия")).put("currency",prefs.getString("currency","RUB")).put("consent",true),stage->ui.post(()->{if(busy&&!isDestroyed())selectionStage(stage);})),this::acceptSelection);
    }

    private byte[] readJpeg(Uri uri)throws Exception{
        BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;try(InputStream input=getContentResolver().openInputStream(uri)){BitmapFactory.decodeStream(input,null,bounds);}if(bounds.outWidth<16||bounds.outHeight<16)throw new IOException("Не удалось прочитать фото.");
        BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=1;while(Math.max(bounds.outWidth,bounds.outHeight)/options.inSampleSize>2200)options.inSampleSize*=2;
        Bitmap bitmap;try(InputStream input=getContentResolver().openInputStream(uri)){bitmap=BitmapFactory.decodeStream(input,null,options);}if(bitmap==null)throw new IOException("Неподдерживаемый формат фото.");
        int orientation=ExifInterface.ORIENTATION_NORMAL;try(InputStream input=getContentResolver().openInputStream(uri)){orientation=new ExifInterface(input).getAttributeInt(ExifInterface.TAG_ORIENTATION,ExifInterface.ORIENTATION_NORMAL);}catch(Exception ignored){}
        Matrix transform=new Matrix();switch(orientation){case 2:transform.setScale(-1,1);break;case 3:transform.setRotate(180);break;case 4:transform.setScale(1,-1);break;case 5:transform.setRotate(90);transform.postScale(-1,1);break;case 6:transform.setRotate(90);break;case 7:transform.setRotate(270);transform.postScale(-1,1);break;case 8:transform.setRotate(270);break;default:break;}
        Bitmap rotated=Bitmap.createBitmap(bitmap,0,0,bitmap.getWidth(),bitmap.getHeight(),transform,true);if(rotated!=bitmap)bitmap.recycle();bitmap=rotated;
        return compress(bitmap,1500);
    }
    private byte[] compress(Bitmap bitmap,int limit)throws IOException{
        double scale=Math.min(1,(double)limit/Math.max(bitmap.getWidth(),bitmap.getHeight()));Bitmap scaled=Bitmap.createScaledBitmap(bitmap,Math.max(1,(int)(bitmap.getWidth()*scale)),Math.max(1,(int)(bitmap.getHeight()*scale)),true);if(scaled!=bitmap)bitmap.recycle();
        ByteArrayOutputStream out=new ByteArrayOutputStream();for(int quality=85;quality>=45;quality-=10){out.reset();scaled.compress(Bitmap.CompressFormat.JPEG,quality,out);if(out.size()<=2*1024*1024)break;}scaled.recycle();if(out.size()>2*1024*1024)throw new IOException("Фото слишком большое даже после сжатия.");return out.toByteArray();
    }
    private void showPhoto(byte[] data,int height){BitmapFactory.Options opt=new BitmapFactory.Options();opt.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(data,0,data.length,opt);opt.inSampleSize=1;while(Math.max(opt.outWidth,opt.outHeight)/opt.inSampleSize>1200)opt.inSampleSize*=2;opt.inJustDecodeBounds=false;Bitmap bitmap=BitmapFactory.decodeByteArray(data,0,data.length,opt);if(bitmap==null)return;ImageView image=new ImageView(this);image.setImageBitmap(bitmap);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setContentDescription("Фото блюда или выбранных продуктов");body.addView(image,new LinearLayout.LayoutParams(-1,dp(height)));}
