    private void selectionStage(String stage){if(prefs.getBoolean("inventoryAppend",false)){message(stage.equals("upload")?"Отправляем только новые фотографии…":"Распознаём новые продукты. Прежний список сохранён…");return;}if(page.equals("review")){String label;switch(stage){case "upload":label="Отправляем подтверждённый список — без фотографий…";break;case "recovering":label="Проверяем прежний подбор. Новый запрос не отправляется…";break;case "upstream_dispatch":case "upstream_headers":case "upstream_body":label="Gemini составляет блюда по вашему списку…";break;case "recipe_validation":label="Проверяем рецепты и расчёты…";break;case "success":label="Подбор готов. Получаем результат…";break;default:label="Список передан. Ожидаем результат…";}message(label);return;}String label;switch(stage){case "recovering":label="Восстанавливаем связь. Проверяем прежний подбор без повторной отправки фото…";break;case "upload":label="Загружаем фотографии…";break;case "validation":case "quota":label="Проверяем фотографии и параметры…";break;case "upstream_dispatch":case "upstream_headers":case "upstream_body":label=prefs.contains("reviewedInventory")?"Составляем блюда из подтверждённых продуктов…":"Распознаём продукты на фотографиях…";break;case "recipe_validation":label="Проверяем рецепты и расчёты…";break;case "success":label="Подбор готов. Получаем результат…";break;default:label="Фотографии переданы. Ожидаем ответ сервера…";}message(label);}
    private void restoreSelection(){try{String saved=prefs.getString("lastSelection",null);if(saved!=null)setSelection(new JSONObject(saved));}catch(Exception ignored){}}
    private void setSelection(JSONObject out)throws Exception{JSONArray recipes=out.getJSONArray("recipes");JSONArray next=new JSONArray();for(int i=0;i<recipes.length();i++)next.put(new JSONObject().put("recipe",recipes.getJSONObject(i)).put("currency",out.optString("currency","RUB")).put("region",out.optString("region",prefs.getString("region","Россия"))).put("id",UUID.randomUUID().toString()));choices=next;}
    private void acceptSelection(Object value)throws Exception{
        JSONObject out=(JSONObject)value;
        if(out.optString("kind").equals("inventory")){
          boolean append=prefs.getBoolean("inventoryAppend",false)&&prefs.contains("reviewedInventory");
          if(!out.optString("status").equals("ok")){prefs.edit().remove(SelectionClient.READY).remove("inventoryAppend").apply();if(append)reviewProducts();else home();message(out.optString("message","Проверьте новые фотографии. Прежний список сохранён."));return;}
          JSONObject inventory=append?PantryMerge.add(new JSONObject(prefs.getString("reviewedInventory","{}")),out):out;
          if(!prefs.edit().putString("reviewedInventory",inventory.toString()).remove(SelectionClient.READY).remove("inventoryAppend").commit())throw new IOException("Не удалось сохранить список продуктов.");
          if(!append){productPhotos.clear();productPhoto=null;receiptPhoto=null;persistInputs();}reviewProducts();if(append)message("Новые продукты добавлены. Проверьте список — прежние фото не отправлялись.");return;
        }
        if(!out.optString("status").equals("ok")){prefs.edit().remove(SelectionClient.READY).apply();JSONObject problem=out.optJSONObject("recipe");if(prefs.contains("reviewedInventory")){reviewProducts();message(out.optString("status").equals("need_details")&&problem!=null?problem.optString("message","Уточните список продуктов."):"Не удалось составить блюда. Подтверждённый список сохранён — фотографии повторно не нужны.");}else{home();message(problem==null?"Нужен другой снимок.":problem.optString("message","Нужен другой снимок."));}return;}
        setSelection(out);if(!prefs.edit().putString("lastSelection",out.toString()).remove(SelectionClient.READY).remove("inventoryAppend").remove("reviewedInventory").commit())throw new IOException("Не удалось сохранить подбор. Не отправляйте фото повторно.");
        productPhotos.clear();productPhoto=null;receiptPhoto=null;persistInputs();showChoices();
    }
    private void resumeSelection(){if(busy)return;task(()->SelectionClient.run(this,null,stage->ui.post(()->{if(busy&&!isDestroyed())selectionStage(stage);})),this::acceptSelection);}
    private void analyze(){
        if(prefs.contains(SelectionClient.PENDING)||prefs.contains(SelectionClient.READY)){resumeSelection();return;}
        prefs.edit().remove("inventoryAppend").apply();final ArrayList<byte[]> photos=new ArrayList<>(productPhotos);if(photos.isEmpty()&&productPhoto!=null)photos.add(productPhoto);final byte[] receipt=receiptPhoto;
        final String region=prefs.getString("region","Россия"),currency=prefs.getString("currency","RUB");
        task(()->{JSONObject request=new JSONObject().put("mode","recognize").put("images",photoUrls(photos)).put("preferences",new JSONArray(prefs.getStringSet("preferences",Collections.emptySet()))).put("region",region).put("currency",currency).put("consent",true);if(receipt!=null)request.put("receipt",dataUrl(receipt));return SelectionClient.run(this,request,stage->ui.post(()->{if(busy&&!isDestroyed())selectionStage(stage);}));},this::acceptSelection);
    }
    private JSONArray kitchen(){return new JSONArray(new TreeSet<>(prefs.getStringSet("equipment",new HashSet<>(Arrays.asList("hob","kettle")))));}
    private void equipmentPicker(){String[][] all={{"hob","Плита"},{"oven","Духовка"},{"microwave","Микроволновка"},{"multicooker","Мультиварка"},{"air_fryer","Аэрогриль"},{"kettle","Чайник"}};Set<String> current=new HashSet<>(prefs.getStringSet("equipment",new HashSet<>(Arrays.asList("hob","kettle"))));for(int i=0;i<all.length;i+=2){LinearLayout row=new LinearLayout(this);for(int j=i;j<i+2&&j<all.length;j++){String code=all[j][0];Button b=buttonView((current.contains(code)?"✓ ":"")+all[j][1],()->{});b.setTextSize(13);b.setBackground(background(current.contains(code)?SOFT:Color.WHITE));b.setOnClickListener(v->{if(current.contains(code))current.remove(code);else current.add(code);prefs.edit().putStringSet("equipment",new HashSet<>(current)).apply();b.setText((current.contains(code)?"✓ ":"")+equipmentName(code));b.setBackground(background(current.contains(code)?SOFT:Color.WHITE));});LinearLayout.LayoutParams x=new LinearLayout.LayoutParams(0,-2,1);x.setMargins(0,dp(4),dp(6),dp(4));row.addView(b,x);}body.addView(row);}muted("Изменения сохраняются сразу. Базовая техника по умолчанию: плита и чайник; проверьте список.");}
    private String equipmentName(String code){switch(code){case "hob":return "Плита";case "oven":return "Духовка";case "microwave":return "Микроволновка";case "multicooker":return "Мультиварка";case "air_fryer":return "Аэрогриль";default:return "Чайник";}}
    private void reviewProducts(){try{JSONObject inv=new JSONObject(prefs.getString("reviewedInventory","{}"));JSONArray products=inv.getJSONArray("products");screen("review","Проверьте продукты");muted("Это распознанные названия, не проверка свежести или количества. Исправьте ошибки — фотографии повторно не нужны.");LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);body.addView(list);Runnable[] render=new Runnable[1];render[0]=()->{list.removeAllViews();for(int i=0;i<products.length();i++){final int n=i;LinearLayout row=new LinearLayout(this);Button name=buttonView(products.optString(i),()->editProduct(inv,products,n,render[0]));name.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);name.setTextSize(14);row.addView(name,new LinearLayout.LayoutParams(0,-2,1));Button remove=buttonView("×",()->{products.remove(n);saveInventory(inv);render[0].run();});remove.setContentDescription("Убрать "+products.optString(i));LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(dp(48),dp(48));rp.leftMargin=dp(6);row.addView(remove,rp);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(6);list.addView(row,lp);}};render[0].run();LinearLayout additions=new LinearLayout(this);Button addText=buttonView("Добавить текстом",()->{if(!busy)editProduct(inv,products,-1,render[0]);});RoundedButton.apply(addText,Color.WHITE,20);addText.setTextSize(13);additions.addView(addText,new LinearLayout.LayoutParams(0,-2,1));Button addPhoto=buttonView("Добавить по фото",()->{if(!busy)photoMenu(false,true);});RoundedButton.apply(addPhoto,Color.WHITE,20);addPhoto.setTextSize(13);LinearLayout.LayoutParams addSpace=new LinearLayout.LayoutParams(0,-2,1);addSpace.leftMargin=dp(8);additions.addView(addPhoto,addSpace);body.addView(additions);muted("Новые фото распознаются отдельно в AnyModel; старые снимки не отправляются, список дополняется. Текст добавляется без обращения к ИИ.");quickPreferences();
      Switch only=new Switch(this);only.setText("Только из моих продуктов");only.setTextSize(15);only.setTextColor(INK);only.setMinHeight(dp(48));only.setChecked(prefs.getBoolean("onlyOwn",false));only.setOnCheckedChangeListener((b,v)->prefs.edit().putBoolean("onlyOwn",v).apply());body.addView(only);muted("По умолчанию доступны: вода, соль, растительное масло и чёрный перец. Вводить их не нужно; проверьте наличие. Остальные обязательные покупки в этом режиме исключены.");
      JSONArray eq=kitchen();ArrayList<String> labels=new ArrayList<>();for(int i=0;i<eq.length();i++)labels.add(equipmentName(eq.optString(i)));muted("Техника: "+(labels.isEmpty()?"без нагрева":String.join(", ",labels))+". Изменяется в настройках.");
      button(CONFIRM_PRODUCTS,()->{if(busy)return;if(prefs.getBoolean("inventoryAppend",false)&&(prefs.contains(SelectionClient.PENDING)||prefs.contains(SelectionClient.READY))){resumeSelection();return;}if(products.length()==0){message("Добавьте хотя бы один продукт.");return;}if(!saveInventory(inv))return;task(()->{JSONObject request=new JSONObject().put("mode","plan").put("targetRecipes",8).put("products",products).put("receiptPrices",inv.optJSONArray("receiptPrices")==null?new JSONArray():inv.optJSONArray("receiptPrices")).put("preferences",new JSONArray(prefs.getStringSet("preferences",Collections.emptySet()))).put("equipment",kitchen()).put("onlyOwn",prefs.getBoolean("onlyOwn",false)).put("region",inv.optString("region","Россия")).put("currency",inv.optString("currency","RUB")).put("consent",true);return SelectionClient.run(this,request,stage->ui.post(()->{if(busy&&!isDestroyed())selectionStage(stage);}));},this::acceptSelection);});muted("Теперь отправится только подтверждённый список и настройки: это отдельный запрос составления рецептов, без повторной загрузки фото.");
    }catch(Exception e){home();message("Не удалось открыть список продуктов. Попробуйте восстановить прежний подбор.");}}
    private boolean saveInventory(JSONObject inv){boolean ok=prefs.edit().putString("reviewedInventory",inv.toString()).commit();if(!ok)message("Не удалось сохранить список. Запрос не отправлен.");return ok;}
    private void editProduct(JSONObject inv,JSONArray products,int index,Runnable render){if(index<0&&products.length()>=80){toast("Можно добавить до 80 продуктов.");return;}EditText edit=new EditText(this);edit.setSingleLine(true);edit.setTextSize(16);edit.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(80)});if(index>=0)edit.setText(products.optString(index));AlertDialog d=new AlertDialog.Builder(this).setTitle(index>=0?"Название продукта":"Добавить продукт").setView(edit).setNegativeButton("Отмена",null).setPositiveButton("Сохранить",null).create();d.setOnShowListener(v->{fitDialog(d);d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(w->{String name=edit.getText().toString().trim();if(name.isEmpty()||name.matches(".*[<>].*")){edit.setError("Введите название без разметки");return;}for(int i=0;i<products.length();i++)if(i!=index&&products.optString(i).equalsIgnoreCase(name)){edit.setError("Такой продукт уже есть");return;}try{if(index<0)products.put(name);else products.put(index,name);if(saveInventory(inv)){render.run();d.dismiss();}}catch(Exception e){edit.setError("Не удалось сохранить");}});});d.show();}
    private String dataUrl(byte[] bytes){return "data:image/jpeg;base64,"+Base64.encodeToString(bytes,Base64.NO_WRAP);}
