    private JSONObject pendingPhoto()throws Exception{return prefs.contains("pendingImage")?new JSONObject(prefs.getString("pendingImage","{}")):null;}
    private File draftFile(){return new File(getFilesDir(),"pending-image.jpg");}
    private void requestPhoto(){if(busy)return;try{JSONObject pending=pendingPhoto();if(pending!=null&&pending.optString("phase").equals("ready")){preview(pending.getJSONObject("snapshot"),readFile(draftFile(),3*1024*1024));return;}if(pending==null&&selected!=null&&imageFile(selected.getJSONObject("recipe")).isFile()){previewSaved();return;}}catch(Exception e){message("Не удалось открыть результат. Прежнее задание сохранено; новая попытка не запущена.");return;}generate(false);}
    private void previewSaved(){try{ImageView image=new ImageView(this);image.setImageBitmap(BitmapFactory.decodeFile(imageFile(selected.getJSONObject("recipe")).getPath()));image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setContentDescription("Сохранённое фото блюда");AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Фото сохранено").setView(image).setPositiveButton("Закрыть",null).create();dialog.setOnShowListener(d->{fitDialog(dialog);image.setMinimumHeight(dp(240));});dialog.show();}catch(Exception e){message("Не удалось открыть сохранённое фото.");}}
    private static String amount(double v){return Math.abs(v-Math.rint(v))<.001?String.valueOf(Math.round(v)):String.format(Locale.getDefault(),"%.1f",v);}
    private String cost(JSONObject recipe,int servings,String currency){
        double lo=0,hi=0;int missing=0;JSONArray list=recipe.optJSONArray("ingredients");for(int i=0;i<list.length();i++){JSONObject x=list.optJSONObject(i),price=x.optJSONObject("price");if(price==null||price.optDouble("quantity",0)<=0){missing++;continue;}double ratio=x.optDouble("amount")/price.optDouble("quantity")*servings/recipe.optInt("servings",2);lo+=price.optDouble("low")*ratio;hi+=price.optDouble("high")*ratio;}
        if(missing==list.length())return "Цена неизвестна";String value=Math.round(lo)==Math.round(hi)?String.format(Locale.getDefault(),"≈ %.0f %s",lo,currency):String.format(Locale.getDefault(),"≈ %.0f–%.0f %s",lo,hi,currency);return missing>0?"Стоимость рассчитана частично":value+" / порция";
    }
    private String compactPrice(String value){return value.replace(" / порция","").replace("RUB","₽").replace("KZT","₸").replace("EUR","€").replace("USD","$");}
    private void share(JSONObject recipe){StringBuilder text=new StringBuilder(recipe.optString("title")+"\n"+Calories.label(recipe)+" (приблизительно)\n\n");JSONArray list=recipe.optJSONArray("ingredients");for(int i=0;i<list.length();i++){JSONObject x=list.optJSONObject(i);text.append(x.optString("name")).append(" — ").append(amount(x.optDouble("amount")*portions/recipe.optInt("servings",2))).append(" ").append(x.optString("unit")).append('\n');}JSONArray steps=recipe.optJSONArray("steps");for(int i=0;i<steps.length();i++)text.append('\n').append(i+1).append(". ").append(steps.optJSONObject(i).optString("body"));Intent intent=new Intent(Intent.ACTION_SEND);intent.setType("text/plain");intent.putExtra(Intent.EXTRA_TEXT,text.toString());startActivity(Intent.createChooser(intent,"Поделиться рецептом"));}
    private void saveSelected()throws Exception{
        selected.put("portions",portions);selected.put("saved",System.currentTimeMillis());JSONArray next=new JSONArray();next.put(new JSONObject(selected.toString()));String key=key(selected.getJSONObject("recipe"));for(int i=0;i<history.length()&&next.length()<50;i++){JSONObject row=history.getJSONObject(i);if(!key(row.getJSONObject("recipe")).equals(key))next.put(row);}writeHistory(next);history=next;
    }
    private void readHistory(){try{history=new JSONArray(new String(readFile(new File(getFilesDir(),"history.json"),16*1024*1024),StandardCharsets.UTF_8));}catch(Exception e){history=new JSONArray();}}
    private void writeHistory(JSONArray value)throws Exception{android.util.AtomicFile file=new android.util.AtomicFile(new File(getFilesDir(),"history.json"));FileOutputStream out=null;try{out=file.startWrite();out.write(value.toString().getBytes(StandardCharsets.UTF_8));file.finishWrite(out);}catch(Exception e){if(out!=null)file.failWrite(out);throw e;}}
    private void showHistory(){readHistory();screen("history","Сохранённое");muted("До 50 рецептов, без интернета. Ищите по названию и продуктам.");
        EditText search=field("Поиск рецепта или продукта",libraryQuery);search.setHint("Например, курица или авокадо");
        LinearLayout controls=new LinearLayout(this);List<String> folders=new ArrayList<>();folders.add("Все");folders.addAll(Library.folders(this));if(!folders.contains(libraryFolder))libraryFolder="Все";Spinner folder=spinner(folders,folders.indexOf(libraryFolder));controls.addView(folder,new LinearLayout.LayoutParams(0,dp(48),1));Button add=buttonView("+ Папка",this::newFolder);controls.addView(add,new LinearLayout.LayoutParams(-2,dp(48)));body.addView(controls);
        LinearLayout results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);body.addView(results);Runnable refresh=()->{results.removeAllViews();LinearLayout outer=body;body=results;int found=0;for(int i=0;i<history.length();i++){JSONObject item=history.optJSONObject(i),r=item.optJSONObject("recipe");if(r!=null&&Library.matches(r,libraryQuery)&&(libraryFolder.equals("Все")||Library.assigned(this,r).contains(libraryFolder))){recipeCard(item,"history");found++;}}if(found==0)card(()->{section(history.length()==0?"Пока здесь пусто":"Ничего не найдено");paragraph(history.length()==0?"Здесь появятся сохранённые рецепты.":"Попробуйте другой запрос или папку.");});body=outer;};
        search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence v,int a,int c,int f){}public void onTextChanged(CharSequence v,int start,int before,int count){libraryQuery=v.toString();refresh.run();}public void afterTextChanged(android.text.Editable e){}});
        folder.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){libraryFolder=folders.get(pos);refresh.run();}});refresh.run();
        if(history.length()>0){space();link("Удалить всю историю и фото","back",()->confirm("Очистить историю?","Все рецепты, оценки, таймеры, переписки и фото Android-приложения будут удалены. Это действие нельзя отменить.",()->{try{writeHistory(new JSONArray());history=new JSONArray();getSharedPreferences("library",0).edit().clear().commit();getSharedPreferences("cooking",0).edit().clear().commit();getSharedPreferences("sous-chef",0).edit().clear().commit();TimerAlarm.cancel(this);prefs.edit().remove("pendingImage").remove("lastSelection").remove(SelectionClient.PENDING).remove(SelectionClient.READY).commit();choices=new JSONArray();draftFile().delete();File[] images=new File(getFilesDir(),"images").listFiles();if(images!=null)for(File f:images)f.delete();showHistory();}catch(Exception e){message("Не удалось очистить историю.");}}));}}
    private String key(JSONObject recipe)throws Exception{String value=recipe.optString("title")+"\n"+recipe.getJSONArray("ingredients").toString()+"\n"+recipe.getJSONArray("steps").toString();byte[] digest=MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));StringBuilder out=new StringBuilder();for(byte b:digest)out.append(String.format(Locale.ROOT,"%02x",b&255));return out.toString();}
    private File imageFile(JSONObject recipe)throws Exception{File folder=new File(getFilesDir(),"images");folder.mkdirs();return new File(folder,key(recipe)+".jpg");}
    private static byte[] readFile(File file,int max)throws Exception{try(InputStream in=new FileInputStream(file);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n,total=0;while((n=in.read(buffer))!=-1){total+=n;if(total>max)throw new IOException("Файл слишком большой.");out.write(buffer,0,n);}return out.toByteArray();}}
